+bool writeAudioSegment(float frequencyHz, uint32_t durationMs,
+                       int16_t amplitude) {
+  if (!audioReady || durationMs == 0) {
+    return false;
+  }
+
+  constexpr size_t kFramesPerBlock = 128;
+  int16_t samples[kFramesPerBlock * 2] = {};
+  const uint32_t totalFrames =
+      static_cast<uint32_t>((static_cast<uint64_t>(kAudioSampleRate) *
+                             durationMs) /
+                            1000ULL);
+  const float phaseStep =
+      frequencyHz > 0.0f
+          ? (2.0f * PI * frequencyHz) / static_cast<float>(kAudioSampleRate)
+          : 0.0f;
+  float phase = 0.0f;
+  uint32_t completedFrames = 0;
+
+  while (completedFrames < totalFrames) {
+    const size_t blockFrames =
+        min(static_cast<uint32_t>(kFramesPerBlock),
+            totalFrames - completedFrames);
+    for (size_t frame = 0; frame < blockFrames; ++frame) {
+      const int16_t sample = frequencyHz > 0.0f
+                                 ? static_cast<int16_t>(sinf(phase) * amplitude)
+                                 : 0;
+      samples[frame * 2] = sample;
+      samples[frame * 2 + 1] = sample;
+      phase += phaseStep;
+      if (phase >= 2.0f * PI) {
+        phase -= 2.0f * PI;
+      }
+    }
+
+    const size_t byteCount = blockFrames * 2 * sizeof(int16_t);
+    const size_t bytesWritten = audioI2s.write(samples, byteCount);
+    if (bytesWritten != byteCount) {
