+                    static_cast<unsigned int>(byteCount),
+                    static_cast<unsigned int>(bytesWritten),
+                    audioI2s.lastError());
+      return false;
+    }
+    completedFrames += blockFrames;
+    audioSamplesWritten += blockFrames;
+    delay(0);
+  }
