static unsigned int velacare_tts_fill(struct ap_buffer_s *apb,
                                      const struct velacare_voice_clip_s *clip,
                                      unsigned int offset)
{
  unsigned int bytes_left;
  unsigned int nbytes;

  if (offset >= clip->nsamples)
    {
      apb->nbytes = 0;
      apb->curbyte = 0;
      apb->nsamples = 0;
      apb->flags = AUDIO_APB_FINAL;
      return offset;
    }

  bytes_left = (clip->nsamples - offset) * sizeof(int16_t);
  nbytes = bytes_left;
  if (nbytes > apb->nmaxbytes)
    {
      nbytes = apb->nmaxbytes;
    }

  memcpy(apb->samp, &clip->samples[offset], nbytes);
  apb->nbytes = nbytes;
  apb->curbyte = 0;
  apb->nsamples = nbytes / sizeof(int16_t);
  offset += apb->nsamples;
  apb->flags = (offset >= clip->nsamples) ? AUDIO_APB_FINAL : 0;
  return offset;
}

static int velacare_tts_enqueue(int fd, struct ap_buffer_s *apb)
{
  struct audio_buf_desc_s desc;
  int ret;

  memset(&desc, 0, sizeof(desc));
  desc.numbytes = apb->nbytes;
  desc.u.buffer = apb;
  ret = ioctl(fd, AUDIOIOC_ENQUEUEBUFFER, (unsigned long)&desc);
  if (ret < 0)
