  if (sensorIndex >= 4 || sensorStates[sensorIndex] == newState) {
    return false;
  }
  const SensorState oldState = sensorStates[sensorIndex];
  sensorStates[sensorIndex] = newState;
  if (newState == kAlarm && oldState != kAlarm) {
