AlarmSeverity highestAlarmSeverity() {
  AlarmSeverity result = kSeverityNotice;
  for (uint8_t sensorIndex = 0; sensorIndex < 4; ++sensorIndex) {
    if (sensorStates[sensorIndex] == kAlarm &&
