static int settings_save(void)
{
  int fd;
  ssize_t written;

  if (mkdir(SETTINGS_DIR, 0755) < 0 && errno != EEXIST)
    {
      return -errno;
    }

  g_settings.checksum = settings_checksum(&g_settings);
  fd = open(SETTINGS_TMP, O_WRONLY | O_CREAT | O_TRUNC, 0644);
  if (fd < 0)
